//
//  EntityFactory.swift
//  MicroLocator
//
//  Builders for every RealityKit entity the app renders. All guidance visuals
//  use UnlitMaterial deliberately: they must read clearly regardless of room
//  lighting, and unlit shading also frees us from caring about mesh normals.
//
//  The arrow cone is generated by hand via MeshDescriptor instead of
//  MeshResource.generateCone — the generator convenience isn't available on
//  our iOS 17 floor, and a 30-line cone is cheaper than an availability dance.
//

import RealityKit
import UIKit

enum EntityFactory {

    private static var materialCache: [String: Material] = [:]

    private static func iconMaterial(name: String, color: UIColor) -> Material {
        if let cached = materialCache[name] { return cached }

        let size = CGSize(width: 256, height: 256)
        let renderer = UIGraphicsImageRenderer(size: size)
        let image = renderer.image { ctx in
            color.setFill()
            ctx.fill(CGRect(origin: .zero, size: size))

            if let symbol = UIImage(systemName: name)?
                .withTintColor(.white, renderingMode: .alwaysOriginal) {
                let symbolSize = symbol.size
                let scale = min(size.width / symbolSize.width, size.height / symbolSize.height) * 0.6
                let scaledSize = CGSize(width: symbolSize.width * scale, height: symbolSize.height * scale)
                let rect = CGRect(
                    x: (size.width - scaledSize.width) / 2,
                    y: (size.height - scaledSize.height) / 2,
                    width: scaledSize.width,
                    height: scaledSize.height
                )
                symbol.draw(in: rect)
            }
        }

        guard let cgImage = image.cgImage,
              let texture = try? TextureResource.generate(from: cgImage, options: .init(semantic: .color)) else {
            return UnlitMaterial(color: color)
        }

        var mat = UnlitMaterial()
        mat.color = .init(tint: .white, texture: .init(texture))
        materialCache[name] = mat
        return mat
    }

    /// Small persistent marker shown where an item was tagged, now with an icon.
    static func itemMarker(iconName: String = "mappin.and.ellipse", color: UIColor = .systemTeal) -> Entity {
        let material = iconMaterial(name: iconName, color: color)
        
        let plane = ModelEntity(
            mesh: .generatePlane(width: 0.05, depth: 0.05, cornerRadius: 0.01),
            materials: [material]
        )
        plane.position = [0, 0.025, 0]
        
        let halo = ModelEntity(
            mesh: .generatePlane(width: 0.09, depth: 0.09, cornerRadius: 0.045),
            materials: [UnlitMaterial(color: color.withAlphaComponent(0.30))]
        )
        halo.position = [0, 0.002, 0]

        let container = Entity()
        container.addChild(plane)
        container.addChild(halo)
        return container
    }

    // MARK: - Guidance visuals (Locate mode)

    /// The floating arrow that hovers above the target and points straight down
    /// at it. The LocateCoordinator's per-frame tick supplies bob + spin, so this
    /// factory only builds geometry.
    static func guidanceArrow(color: UIColor = .systemYellow) -> Entity {
        let cone = ModelEntity(
            mesh: coneMesh(radius: 0.05, height: 0.13, segments: 28, apexDown: true),
            materials: [UnlitMaterial(color: color)]
        )

        // A thin "tail" above the cone reads as an arrow shaft from a distance.
        let tail = ModelEntity(
            mesh: .generateBox(size: SIMD3<Float>(0.018, 0.10, 0.018), cornerRadius: 0.006),
            materials: [UnlitMaterial(color: color)]
        )
        tail.position = [0, 0.13 + 0.05, 0]

        let container = Entity()
        container.addChild(cone)
        container.addChild(tail)
        return container
    }

    /// Translucent ring on the exact saved point — the "X marks the spot" that
    /// stays put while the arrow animates above it.
    static func targetRing(color: UIColor = .systemYellow) -> ModelEntity {
        let ring = ModelEntity(
            mesh: .generatePlane(width: 0.16, depth: 0.16, cornerRadius: 0.08),
            materials: [UnlitMaterial(color: color.withAlphaComponent(0.35))]
        )
        ring.position = [0, 0.004, 0]
        return ring
    }

    // MARK: - Reticle preview (non-LiDAR placement)

    /// Live preview shown under the crosshair while a tracked raycast refines.
    /// The raycast result's orientation aligns +Y with the surface normal, so
    /// this flat ring naturally lies on floors/shelves and faces out on walls
    /// and furniture fronts.
    static func reticlePreview(color: UIColor = .white) -> Entity {
        let ring = ModelEntity(
            mesh: .generatePlane(width: 0.08, depth: 0.08, cornerRadius: 0.04),
            materials: [UnlitMaterial(color: color.withAlphaComponent(0.55))]
        )
        ring.position = [0, 0.002, 0]

        let dot = ModelEntity(
            mesh: .generateSphere(radius: 0.006),
            materials: [UnlitMaterial(color: color)]
        )
        dot.position = [0, 0.006, 0]

        let container = Entity()
        container.addChild(ring)
        container.addChild(dot)
        return container
    }

    // MARK: - Custom cone mesh

    /// Fan-triangulated cone. Every triangle is emitted with *both* windings —
    /// a cheap double-siding trick that makes face-culling irrelevant, so the
    /// arrow can never vanish from an unlucky viewing angle.
    private static func coneMesh(
        radius: Float,
        height: Float,
        segments: Int,
        apexDown: Bool
    ) -> MeshResource {
        var positions: [SIMD3<Float>] = []
        var indices: [UInt32] = []

        let apexY: Float = apexDown ? 0 : height
        let baseY: Float = apexDown ? height : 0

        positions.append([0, apexY, 0])   // 0: apex
        positions.append([0, baseY, 0])   // 1: base center

        for i in 0..<segments {
            let angle = Float(i) / Float(segments) * 2 * .pi
            positions.append([radius * cos(angle), baseY, radius * sin(angle)])
        }

        for i in 0..<segments {
            let current = UInt32(2 + i)
            let next = UInt32(2 + (i + 1) % segments)

            // Side + base cap, both windings each.
            indices += [0, current, next,  0, next, current]
            indices += [1, current, next,  1, next, current]
        }

        var descriptor = MeshDescriptor(name: "guidance-cone")
        descriptor.positions = MeshBuffers.Positions(positions)
        descriptor.primitives = .triangles(indices)

        // generate(from:) only throws on malformed descriptors; this one is
        // statically well-formed, so a failure here is a programmer error.
        return try! MeshResource.generate(from: [descriptor])
    }

    // MARK: - Confetti
    
    static func confetti() -> Entity {
        let halo = ModelEntity(
            mesh: .generatePlane(width: 0.3, depth: 0.3, cornerRadius: 0.15),
            materials: [UnlitMaterial(color: UIColor.systemGreen.withAlphaComponent(0.6))]
        )
        halo.position = [0, 0.05, 0]
        return halo
    }
}
